// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {GameItems} from "../src/GameItems.sol";

contract InvMutTest is Test {
    GameItems c;

    bytes4 constant ERC1155_ID = type(IERC1155Probe).interfaceId;
    bytes4 constant META_ID = 0x0e89341c;

    function setUp() public { c = new GameItems(address(this), address(this)); }

    function testFuzz_property(uint256 mode, bytes4 extra) public {
        bytes4 queried;
        if (mode % 4 == 0) {
            queried = ERC1155_ID;
        } else if (mode % 4 == 1) {
            queried = META_ID; // ERC1155MetadataURI interface id
        } else if (mode % 4 == 2) {
            queried = type(IERC165Probe).interfaceId;
        } else {
            vm.assume(extra != ERC1155_ID && extra != META_ID && extra != type(IERC165Probe).interfaceId);
            queried = extra;
        }
        bool ok = c.supportsInterface(queried);
        assertTrue(
            ok == (queried == ERC1155_ID || queried == META_ID || queried == type(IERC165Probe).interfaceId)
        );
    }
}

interface IERC1155Probe {
    function safeTransferFrom(address, address, uint256, uint256, bytes calldata) external;
    function safeBatchTransferFrom(address, address, uint256[] calldata, uint256[] calldata, bytes calldata) external;
    function balanceOf(address, uint256) external view returns (uint256);
    function balanceOfBatch(address[] calldata, uint256[] calldata) external view returns (uint256[] memory);
    function setApprovalForAll(address, bool) external;
    function isApprovedForAll(address, address) external view returns (bool);
}

interface IERC165Probe {
    function supportsInterface(bytes4) external view returns (bool);
}
